const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function messageDesign(m){try{return JSON.parse(m.body.split('Designentwurf (JSON):\n')[1])}catch{return null}}
let core={},mode='',folder='inbox';
async function api(path,data){const r=await fetch(path,{method:data?'POST':'GET',headers:data?{'Content-Type':'application/json'}:undefined,body:data?JSON.stringify(data):undefined});const v=await r.json();if(!r.ok)throw Error(v.error||'Anfrage fehlgeschlagen.');return v;}
function show(title,tag,body){mode=tag;const d=$('#coreDialog');d.innerHTML=`<div class="core-heading"><div><span class="kicker">${tag}</span><h2 id="coreTitle">${title}</h2></div><button class="icon-button" data-core-close aria-label="Fenster schließen">×</button></div>${body}<p id="coreStatus" role="status"></p>`;if(!d.open)d.showModal();d.querySelector('[data-core-close]').onclick=()=>d.close();}
function status(s){const el=$('#coreStatus');if(el)el.textContent=s;}
const back='<div class="core-divider"><button class="button" data-core="dashboard">← Admin Menü</button></div>';
function bind(){document.querySelectorAll('[data-core]').forEach(b=>b.onclick=()=>open(b.dataset.core));}
export function setupShopCore(){for(const footer of document.querySelectorAll('footer')){const links=footer.querySelector('.footer-links')||footer;if(!footer.querySelector('[data-footer-withdrawal]'))links.insertAdjacentHTML('beforeend','<a class="neon-flow footer-withdrawal" data-footer-withdrawal href="/widerruf">Vertrag widerrufen</a>');}const header=$('header');header.insertAdjacentHTML('beforeend',`<div class="shop-menu"><button class="icon-button" id="shopMenuButton" aria-label="Shop-Menü öffnen" aria-expanded="false" aria-controls="shopMenu"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><path d="M4 6h16M4 12h16M4 18h16"/></svg></button><div id="shopMenu" class="shop-menu-popup" hidden><button data-share>↗ Seite teilen</button><a href="/impressum">Impressum</a><a href="/datenschutz">Datenschutz</a><a href="/verkaufshinweise">Verkaufs- und Lieferhinweise</a><a href="/widerrufsbelehrung">Widerrufsbelehrung</a><a class="withdraw-link" href="/widerruf">Vertrag widerrufen</a><button data-core="contact">✉ Kontakt</button><hr><button data-core="dashboard">⌁ Login</button></div></div>`);document.body.insertAdjacentHTML('beforeend','<dialog id="coreDialog" class="core-dialog" aria-labelledby="coreTitle"></dialog>');$('#shopMenuButton').onclick=()=>{const p=$('#shopMenu');p.hidden=!p.hidden;$('#shopMenuButton').setAttribute('aria-expanded',String(!p.hidden));};document.addEventListener('click',e=>{if(!e.target.closest('.shop-menu')){$('#shopMenu').hidden=true;$('#shopMenuButton').setAttribute('aria-expanded','false');}});$('#shopMenu [data-share]').onclick=async()=>{try{if(navigator.share)await navigator.share({title:document.title,url:location.href});else{await navigator.clipboard.writeText(location.href);show('Link kopiert','NEONMIND · SHOP','<p>Die Seitenadresse liegt jetzt in deiner Zwischenablage.</p>');}}catch(e){if(e.name!=='AbortError')show('Seite teilen','NEONMIND · SHOP',`<p>Kopiere diese Adresse:</p><input aria-label="Seitenadresse" value="${esc(location.href)}" readonly>`);}};bind();window.openShopAdmin=()=>open('dashboard');window.openShopContact=()=>open('contact');document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('#shopMenu').hidden=true;$('#shopMenuButton').setAttribute('aria-expanded','false');}});}
async function login(){show('NeonMind Shop','ADMIN · LOGIN',`<p>Melde dich mit deinem freigeschalteten Betreiberkonto an.</p><form id="coreLogin"><label class="field">E-Mail-Adresse<input name="email" type="email" autocomplete="username" required></label><label class="field">Admin-Passwort<input name="password" type="password" autocomplete="current-password" required></label><button class="button primary" type="submit">Einloggen →</button></form>`);$('#coreLogin').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;try{await api('/api/login',Object.fromEntries(new FormData(e.target)));await open('dashboard');}catch(err){status(err.message)}finally{button.disabled=false}};}
export async function open(which){$('#shopMenu').hidden=true;try{
 if(which==='contact'){show('Schreib uns.','NEONMIND SHOP · KONTAKT',`<p>Fragen zum Shop, zu einem Produkt oder zu deiner Bestellung? Deine Nachricht landet direkt in unserem Shop-Postfach.</p><form id="contactForm"><div class="core-grid"><label class="field">Dein Name *<input name="name" maxlength="100" minlength="2" required autocomplete="name"></label><label class="field">Deine E-Mail *<input name="email" type="email" maxlength="180" required autocomplete="email"></label></div><label class="field">Betreff *<input name="subject" maxlength="120" required></label><label class="field">Nachricht *<textarea name="message" minlength="20" maxlength="3000" rows="5" required></textarea></label><label class="core-hp" aria-hidden="true">Website<input name="website" tabindex="-1" autocomplete="off"></label><label class="check"><input name="consent" type="checkbox" required>Ich habe die <a href="/datenschutz" target="_blank" rel="noopener">Datenschutzhinweise</a> gelesen und stimme der Verarbeitung meiner Angaben zur Bearbeitung zu.</label><button class="button primary" type="submit">Nachricht senden →</button></form>`);$('#contactForm').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{const values=Object.fromEntries(new FormData(e.target));values.consent=e.target.elements.consent.checked;const r=await api('/api/contact',values);e.target.reset();status('Deine Nachricht ist angekommen. Referenz: '+r.id+' · Wir senden dir eine Eingangsbestätigung per E-Mail.');}catch(err){status(err.message)}finally{b.disabled=false}};return;}
 core=await api('/api/admin/core');
 if(which==='dashboard'){show('Admin Menü','ADMIN · SHOP',`<div class="core-inbox-heading"><strong>Aktuelle Nachrichten</strong><span>${core.unread} ungelesen</span></div><div class="core-recent">${core.recent.length?core.recent.map(m=>`<p>${esc(m.subject)} <small>${new Date(m.created_at).toLocaleDateString('de-DE')}</small></p>`).join(''):'Keine neuen Nachrichten.'}</div><div class="core-grid"><button class="button" data-core="mailbox">✉ Zum Postfach →</button><button class="button" id="coreArticles">◇ Artikel bearbeiten →</button><button class="button" data-core="packages">⇩ Downloads →</button><button class="button" data-core="users">◎ User-Verwaltung →</button><button class="button" data-core="maintenance">⚙ Wartungsmodus →</button><button class="button" data-core="mail">✉ Info-Mails →</button><button class="button" data-core="payments">◇ Zahlungen & Testmodus →</button></div><p class="muted">Shop ${core.maintenance.enabled?'im Wartungsmodus':'öffentlich'} · Mailversand ${core.mail.configured?'eingerichtet':'noch nicht eingerichtet'}</p><button class="button danger" id="coreLogout">Abmelden</button>`);$('#coreArticles').onclick=()=>{$('#coreDialog').close();window.openShopArticles();};$('#coreLogout').onclick=async()=>{await api('/api/logout',{});location.assign('/admin');};}
 if(which==='mailbox'){const r=await api('/api/admin/mailbox?folder='+folder);show('NeonMind Shop Postfach','ADMIN · POSTFACH',`<div class="core-tabs">${[['inbox','Posteingang'],['saved','Gespeichert'],['trash','Papierkorb']].map(([id,label])=>`<button class="button ${folder===id?'primary':''}" data-folder="${id}">${label}</button>`).join('')}<button class="button" data-core="mailbox" aria-label="Postfach aktualisieren">↻</button></div><div class="core-messages">${r.messages.length?r.messages.map(m=>`<article class="core-message"><div class="core-inbox-heading"><strong>${esc(m.subject)}</strong><span>${m.read_at?'GELESEN':'NEU'}</span></div><small>${esc(m.name)} · ${esc(m.email)} · ${new Date(m.created_at).toLocaleString('de-DE')}</small><p class="message-body">${esc(m.body)}</p><div class="core-message-actions">${messageDesign(m)?`<button class="button" data-open-design="${esc(m.id)}">Designentwurf öffnen →</button>`:''}<button class="button" data-message="${esc(m.id)}" data-action="${m.read_at?'unread':'read'}">${m.read_at?'Als ungelesen':'Als gelesen'}</button>${folder!=='trash'?`<button class="button" data-message="${esc(m.id)}" data-action="${folder==='saved'?'restore':'save'}">${folder==='saved'?'Zurück in Eingang':'☆ Speichern'}</button><button class="button" data-message="${esc(m.id)}" data-action="trash">× Papierkorb</button>`:`<button class="button" data-message="${esc(m.id)}" data-action="restore">Wiederherstellen</button>`}${m.email?`<a class="button" href="mailto:${encodeURIComponent(m.email)}?subject=${encodeURIComponent('Re: '+m.subject)}">Antworten ↗</a>`:''}</div></article>`).join(''):'<p>Dieser Ordner ist leer.</p>'}</div><p class="muted">Wunsch- und Kontakt-Nachrichten werden 90 Tage aufbewahrt, auch in Gespeichert und Papierkorb. Bestellhinweise bleiben erhalten.</p>${back}`);document.querySelectorAll('[data-open-design]').forEach(b=>b.onclick=()=>{const draft=messageDesign(r.messages.find(m=>m.id===b.dataset.openDesign));if(draft){localStorage.setItem('nm-design-draft',JSON.stringify(draft));location.href='/gestalter.html?review=1&package='+encodeURIComponent(draft.productId||'designstudio')+'&category='+encodeURIComponent(draft.category);}});document.querySelectorAll('[data-folder]').forEach(b=>b.onclick=()=>{folder=b.dataset.folder;open('mailbox');});document.querySelectorAll('[data-message]').forEach(b=>b.onclick=async()=>{try{await api('/api/admin/mailbox',{id:b.dataset.message,action:b.dataset.action});await open('mailbox')}catch(e){status(e.message)}});}
 if(which==='payments'){
  const p=await api('/api/admin/payments');show('Zahlungen & Testmodus','ADMIN · ZAHLUNGEN',`<p>Live-Verkauf: <strong>${p.paymentsEnabled?'aktiv':'noch nicht freigeschaltet'}</strong></p><p>Automatische Steuerberechnung: <strong>${p.automaticTaxEnabled?'technisch aktiviert':'vorbereitet, noch nicht aktiviert'}</strong></p><p>Stripe Live-Anschluss: ${p.liveConfigured?'Schlüssel hinterlegt':'noch einzurichten'} · Sandbox: ${p.sandboxConfigured?'eingerichtet':'noch einzurichten'}</p>${p.configuration?.liveKey?'<p>Live-Schlüssel: '+(p.configuration.liveKey.formatValid?'Format erkannt':p.configuration.liveKey.present?'Format nicht erkannt':'fehlt')+' · Live-Webhook-Geheimnis: '+(p.configuration.liveWebhook.formatValid?'Format erkannt':p.configuration.liveWebhook.present?'Format nicht erkannt':'fehlt')+'.</p>':''}${p.configuration?'<p>Sandbox-Testschlüssel: '+(p.configuration.sandboxKey.formatValid?'Format erkannt':p.configuration.sandboxKey.present?'Format nicht erkannt':'fehlt')+' · Webhook-Geheimnis: '+(p.configuration.sandboxWebhook.formatValid?'Format erkannt':p.configuration.sandboxWebhook.present?'Format nicht erkannt':'fehlt')+'.</p>':''}<p><a class="button primary" href="/checkout" id="operatorCheckout">Warenkorb im Betreiber-Test prüfen →</a></p><p>Lege dafür Produkte in den Warenkorb. In der Kasse kannst du ohne Geldzahlung den Ablauf und die vollständigen ZIP-Pakete testen. Der Zugriff ist ausschließlich für dein Betreiberkonto freigegeben.</p><label class="field">Live-Webhook<input readonly value="${esc(p.webhook)}"></label><label class="field">Sandbox-Webhook<input readonly value="${esc(p.sandboxWebhook)}"></label><p>Die Stripe-Schlüssel werden als geschützte Cloudflare-Secrets hinterlegt. Bitte keine Schlüssel in Nachrichten oder Produkttexte schreiben.</p><p><button class="button" id="checkStripeConnection">Stripe-Live-Verbindung prüfen</button></p><p><button class="button" id="auditPackages">Private Pakete auf Vollständigkeit prüfen</button></p><p class="notice">Verkaufsstart geplant: 02.01.2027. Die Katalogpreise sind Endpreise inklusive anfallender Umsatzsteuer. Für den geplanten weltweiten Verkauf müssen Steuerregistrierungen und die internationale Steuerberechnung vor der Freischaltung abgeschlossen werden. Der Wartungsmodus blockiert echte Käufe zusätzlich zur Zahlungseinstellung.</p><form id="paymentSettings"><label class="check"><input name="readinessConfirmed" type="checkbox" required>Betreiberangaben, Verkaufsbedingungen, Widerrufshinweise, Steuerdarstellung, Bestellbestätigung und Lieferablauf sind für den echten Verkaufsbetrieb eingerichtet und geprüft.</label><button class="button primary" ${!p.liveConfigured?'disabled':''}>Echte Zahlungen freischalten</button></form><p><button class="button danger" id="disablePayments">Echte Zahlungen deaktivieren</button></p>${back}`);$('#checkStripeConnection').onclick=async()=>{status('Stripe-Verbindung wird ohne Zahlung geprüft …');try{const r=await api('/api/admin/payments?verify=true');status(r.connection?.ok?'Live-API-Schlüssel von Stripe angenommen. Lesezugriff auf Checkout-Sitzungen bestätigt. Es wurde keine Zahlung ausgelöst.':({key_missing_or_invalid:'Live-Schlüssel fehlt oder hat ein falsches Format.',authentication_failed:'Stripe lehnt den Live-Schlüssel ab.',permission_denied:'Dem Schlüssel fehlt die Checkout-Berechtigung.',stripe_unavailable:'Stripe ist derzeit nicht erreichbar.',unexpected_response:'Stripe hat unerwartet geantwortet.'})[r.connection?.status]||'Verbindung nicht bestätigt.')}catch(e){status(e.message)}};$('#auditPackages').onclick=async()=>{status('Private Dateien werden geprüft ...');try{const a=await api('/api/admin/payment-audit');status(a.ready+' von '+a.downloadProducts+' Downloadpaketen vorhanden und mit korrekter Dateigröße; '+a.services+' Dienstleistungen. '+(a.missing.length?'Fehlend: '+a.missing.join(', '):'Keine fehlenden Pakete.'));}catch(err){status(err.message)}};$('#operatorCheckout').onclick=()=>$('#coreDialog').close();$('#paymentSettings').onsubmit=async e=>{e.preventDefault();try{await api('/api/admin/payments',{enabled:true,readinessConfirmed:true});await open('payments');status('Echte Zahlungen aktiviert.')}catch(err){status(err.message)}};$('#disablePayments').onclick=async()=>{try{await api('/api/admin/payments',{enabled:false});await open('payments');status('Zahlungen deaktiviert. Bereits bezahlte Downloads bleiben erreichbar.')}catch(err){status(err.message)}};
 }

 if(which==='maintenance'){const m=core.maintenance;show('Wartungsmodus','ADMIN · SHOP-WARTUNG',`<p>Aktuell: <strong>${m.enabled?'Wartungsmodus aktiv':'Shop öffentlich'}</strong></p><div class="core-grid"><button class="button ${!m.enabled?'primary':''}" id="makePublic">Shop öffentlich</button><button class="button ${m.enabled?'primary':''}" id="makePrivate">Wartungsmodus jetzt</button></div>${back}<form id="maintenanceForm"><span class="kicker">WARTUNGSSEITE · TEXTE</span><label class="field">Systemstatus<textarea name="status" rows="6" maxlength="2000">${esc(m.status)}</textarea></label><p class="muted">Eine Zeile pro Eintrag: Name | Status</p><label class="field">Wartungsmodus Info<textarea name="info" rows="4" maxlength="2000">${esc(m.info)}</textarea></label><button class="button primary" type="submit">Wartungsseite speichern</button></form><p class="muted">Gilt nur für den Shop. Betreiber können den Shop weiterhin ansehen. Impressum, Datenschutz und Kontakt bleiben erreichbar.</p>`);const save=async enabled=>{const values=Object.fromEntries(new FormData($('#maintenanceForm')));try{await api('/api/admin/maintenance',{...values,enabled});await open('maintenance');status('Gespeichert.')}catch(err){status(err.message)}};$('#makePublic').onclick=()=>save(false);$('#makePrivate').onclick=()=>save(true);$('#maintenanceForm').onsubmit=e=>{e.preventDefault();save(m.enabled);};}
 if(which==='users'){const r=await api('/api/admin/users');show('User-Verwaltung','ADMIN · SHOP',`<p>Kundenkonten und Bestellanzahl. Eine Sperre beendet bestehende Sitzungen; Bestellungen bleiben erhalten.</p><div class="core-messages">${r.users.map(u=>`<article class="core-message"><strong>${esc(u.email)}</strong><p>${u.admin?'Betreiber':u.blocked?'Gesperrt':'Aktiv'} · ${u.orders} Bestellungen · seit ${new Date(u.created_at).toLocaleDateString('de-DE')}</p>${!u.admin?`<button class="button" data-user="${esc(u.id)}" data-block="${u.blocked?'false':'true'}">${u.blocked?'Entsperren':'Konto sperren'}</button>`:''}</article>`).join('')||'<p>Noch keine Konten.</p>'}</div>${back}`);document.querySelectorAll('[data-user]').forEach(b=>b.onclick=async()=>{try{await api('/api/admin/users',{id:b.dataset.user,blocked:b.dataset.block==='true'});await open('users')}catch(e){status(e.message)}});}
 if(which==='packages'){const r=await api('/api/admin/state');show('Downloads','ADMIN · PRODUKTPAKETE',`<p>Deine privaten ZIP-Pakete. Diese Links funktionieren nur mit deinem Betreiberkonto.</p><div class="core-messages">${r.files.map(f=>`<article class="core-message"><strong>${esc(r.products.find(p=>p.id===f.product_id)?.name||f.product_id)}</strong><p>${esc(f.filename)} · ${(f.size/1048576).toFixed(1)} MB</p><a class="button" href="/api/admin/package/${encodeURIComponent(f.product_id)}">Paket herunterladen ↓</a></article>`).join('')||'<p>Noch keine Pakete.</p>'}</div>${back}`);}
 if(which==='mail'){show('Info-Mails','ADMIN · BENACHRICHTIGUNGEN',`<p>Neue Wünsche, Kontakt-Nachrichten und Bestellungen melden sich bei <strong>info@neonmind-ai.com</strong>. Die Mails enthalten nur die Art der Bewegung und einen Link zum Postfach.</p><p>${core.notifications.map(n=>`${n.n} ${n.state==='sent'?'versendet':'ausstehend'}`).join(' · ')||'Noch keine Versandaufträge.'}</p>${core.failures.length?'<p class="notice">Ein Versandversuch ist fehlgeschlagen. Bitte Zugang und SMTP-Freigabe prüfen.</p>':''}<h3>Kundenbestätigungen</h3><p>Kontakt- und Wunschanfragen erhalten eine Eingangsbestätigung. Echte Bestellungen erhalten einen Bestelleingang und nach erfolgreicher Zahlungsprüfung eine Zahlungsbestätigung. Betreiber- und Sandbox-Testbestellungen erzeugen keine Kundenmails.</p><p>Absender und Antwortadresse: <strong>${esc(core.mail.user||'Versandkonto noch einrichten')}</strong></p><p>${(core.customerNotifications||[]).map(n=>`${n.n} ${esc(({sent:'versendet',pending:'ausstehend',sending:'im Versand',failed:'fehlgeschlagen',skipped:'übersprungen'})[n.state]||n.state)}`).join(' · ')||'Noch keine Kundenmails.'}</p>${core.customerFailures?.length?'<p class="notice">Eine Kundenmail konnte nicht zugestellt werden. Bitte Versandzugang prüfen. Nach sechs erfolglosen Versuchen ist ein manueller Neustart erforderlich.</p>':''}<form id="smtpForm"><label class="field">Versandanbieter<select name="provider"><option value="gmx">GMX</option><option value="ionos">IONOS</option></select></label><label class="field">E-Mail-Adresse des Versandkontos<input type="email" name="user" required maxlength="180" autocomplete="off" value="${esc(core.mail.user)}"></label><label class="field">SMTP-Passwort / App-Passwort<input type="password" name="password" maxlength="256" autocomplete="new-password" placeholder="${core.mail.configured?'Leer lassen, um das Passwort beizubehalten':'Versandpasswort eintragen'}"></label><p class="muted">GMX: POP3/IMAP und SMTP im GMX-Konto freigeben; bei Zwei-Faktor-Anmeldung ein App-Passwort verwenden. Die Absenderadresse muss zum Versandkonto gehören. Das Passwort wird verschlüsselt gespeichert und nicht wieder angezeigt.</p><button class="button primary" type="submit">Versandzugang speichern</button></form><div class="core-tabs"><button class="button" id="smtpTest">Testmail senden</button><button class="button" id="smtpRetry">Mailversand erneut versuchen</button></div>${back}`);$('#smtpForm').elements.provider.value=core.mail.provider;$('#smtpForm').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{await api('/api/admin/mail-settings',Object.fromEntries(new FormData(e.target)));await open('mail');status('Versandzugang gespeichert. Bitte jetzt eine Testmail senden.')}catch(err){status(err.message)}finally{b.disabled=false}};for(const [id,url]of [['smtpTest','mail-test'],['smtpRetry','mail-retry']])$('#'+id).onclick=async e=>{e.target.disabled=true;status('Versand läuft …');try{const r=await api('/api/admin/'+url,{});await open('mail');status(r.message||'Versandversuch abgeschlossen. Status oben aktualisiert.')}catch(err){status(err.message)}finally{e.target.disabled=false}};}
 bind();
 }catch(err){if(/anmelden|Betreiberkonto/.test(err.message))await login();else{show('Admin Menü','ADMIN · SHOP',`<p>${esc(err.message)}</p>`);}}
}
